#include<bits/stdc++.h>
#include<boost/multiprecision/cpp_int.hpp>
using namespace std;using boost::multiprecision::cpp_int;
struct D{cpp_int n=0;int e=0;D(){}D(int x):n(x){}void norm(){if(n==0){e=0;return;}cpp_int a=n<0?-n:n;int k=min(e,(int)boost::multiprecision::lsb(a));n>>=k;e-=k;}D mul(long long a,long long b)const{assert(b>0&&(b&(b-1))==0);D z=*this;z.n*=a;z.e+=countr_zero((unsigned long long)b);z.norm();return z;}D operator+(D const&b)const{D z;z.e=max(e,b.e);z.n=(n<<(z.e-e))+(b.n<<(z.e-b.e));z.norm();return z;}bool operator==(D const&b)const{return n==b.n&&e==b.e;}};
int main(int ac,char**av){if(ac!=3)return 2;ifstream in(av[1]);int n,V,runs;in>>n>>V>>runs;assert(n==728&&V==112&&runs==4);vector<vector<D>>base;vector<long long>diffs,targetdiffs;
for(int run=0;run<runs;run++){vector<vector<D>>A(n,vector<D>(n));for(int i=0;i<n;i++)A[i][i]=D(1);int m;in>>m;for(int k=0;k<m;k++){int kind,t,s;long long a,b;in>>kind>>t>>s>>a>>b;assert(t>=0&&t<n);for(int j=0;j<n;j++)if(kind)A[t][j]=A[t][j].mul(a,b);else if(A[s][j].n!=0)A[t][j]=A[t][j]+A[s][j].mul(a,b);}if(run==0){base=move(A);continue;}long long diff=0,tdiff=0;for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(!(base[i][j]==A[i][j])){diff++;tdiff+=i>=V&&i<2*V;}diffs.push_back(diff);targetdiffs.push_back(tdiff);if(run==1)assert(diff==0);else assert(diff>0);}
ofstream out(av[2]);out<<"{\"status\":\"PASS\",\"initial_columns\":"<<n<<",\"output_rows\":"<<n<<",\"exact_coefficients_checked\":"<<n*n<<",\"arithmetic\":\"cpp_int dyadic rational\",\"controls\":[{\"name\":\"omit terminal inverse\",\"differing_coefficients\":"<<diffs[1]<<",\"differing_target_coefficients\":"<<targetdiffs[1]<<"},{\"name\":\"omit transformed reader\",\"differing_coefficients\":"<<diffs[2]<<",\"differing_target_coefficients\":"<<targetdiffs[2]<<"}]}\n";cout<<"PASS full endpoint and two nonvacuous controls"<<endl;}
